#!/usr/bin/env python3
"""Build the local, dependency-free photo atlas from the research recipe data."""
from pathlib import Path
import json, html
root=Path(__file__).resolve().parents[1]
out=root/'docs/habitat-atlas'
items=json.loads((root/'data/habitat_recipes.json').read_text())['habitats']
meta={m['id']:m for m in json.loads((out/'provenance.json').read_text())}
e=html.escape
cards=[]
for i,item in enumerate(items):
 m=meta[item['id']]
 group='chemical' if item['id'] in ['vent','seep','brine'] else 'deepest' if item['id']=='hadal' else 'foodfall' if item['id']=='whale' else 'terrain'
 details=''.join(f'<h4>{title}</h4><p>{e(item[key])}</p>' for title,key in [('Terrain to build','terrain'),('Movement and atmosphere','movement'),('Arrival','arrival'),('Exploration scenario','scenario'),('Research direction · proposed gameplay','research')])
 supplement = ''
 if item['id']=='seep':
  extra=meta['bubbles']
  supplement=f'<h4>A different seep: bubbles and mixed attached life</h4><a href="images/bubbles.jpg"><img src="images/bubbles.jpg" alt="NOAA Alaska cold seep with an escaping bubble stream and surrounding attached life" loading="lazy" style="width:100%;height:auto"></a><p class="site">{e(extra["credit"])} · Public domain · Resized/re-encoded, no content edits. <a href="{e(extra["page"])}">Original source</a></p>'
 rules=''.join('<li>'+e(v)+'</li>' for v in item['rules'])
 variations=' / '.join(item['variations'])
 cards.append(f'''<article id="{item['id']}" data-group="{group}" tabindex="-1">
 <a class="photo" href="{item['image']}" target="_blank" aria-label="Open {e(item['name'])} reference photograph"><img src="{item['image']}" alt="{e(item['look'])}" loading="lazy"></a>
 <div class="card-body"><p class="eyebrow">{i+1:02d} / {e(item['tag'])}</p><h3>{e(item['name'])}</h3><p>{e(item['look'])}</p>
 <div class="chips">{''.join('<span>'+e(v)+'</span>' for v in item['life'])}</div>
 <p class="site">Reference: {e(item['reference'])}</p>
 <details><summary>Explore the habitat recipe</summary>{details}<h4>Generator constraints</h4><ul>{rules}</ul><h4>Variations within this habitat</h4><p>{e(variations)}</p><p class="note">{e(item['certainty'])}</p>{supplement}</details>
 <footer><p>{e(m['credit'])} · <a href="{e(m['license_url'])}">{e(m['license'])}</a></p><p><a href="{e(m['page'])}">Original source ↗</a> · Reference copy resized/re-encoded; no content edits.</p></footer></div></article>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>A World Below · Habitat Atlas</title><style>
:root{color-scheme:dark;--ink:#d9e7e5;--muted:#a3bdbd;--mint:#87ddc5;--panel:#0b2029;--line:#29454e}*{box-sizing:border-box}body{margin:0;background:#04121b;color:var(--ink);font:17px/1.6 system-ui,sans-serif}main,header{max-width:1200px;margin:auto;padding:36px 24px}header{padding-top:64px;padding-bottom:12px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--mint)}h1{font-size:clamp(36px,6vw,68px);line-height:1.05;font-weight:600;margin:18px 0 24px;max-width:850px}h2{font-size:30px;font-weight:550}h3{font-size:27px;line-height:1.2;margin:10px 0 18px}h4{font-size:16px;color:var(--mint);margin:22px 0 6px}p{margin:10px 0}header>p:not(.eyebrow){max-width:860px;color:var(--muted);font-size:20px}a{color:var(--mint);text-underline-offset:4px}button{cursor:pointer;border:1px solid var(--line);background:#0e2b34;color:var(--ink);font:inherit;border-radius:22px;padding:10px 18px;min-height:44px}button:hover,button[aria-pressed=true]{background:#27564f;border-color:var(--mint)}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #f2c68d;outline-offset:5px}.note{padding:20px;border-left:3px solid #ddb887;background:#14252b;color:#cfdbd6;margin:24px 0}.map-panel{border:1px solid var(--line);border-radius:16px;overflow:hidden;background:linear-gradient(120deg,#102e38,#06131e);padding:20px}.map-head{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap}.map-head h2{margin:0}svg{width:100%;height:auto;display:block;margin-top:24px;touch-action:pan-y}.map-label{font:15px system-ui;fill:#d9e7e5;paint-order:stroke;stroke:#071721;stroke-width:5px;stroke-linejoin:round}.map-link:focus circle,.map-link:hover circle{stroke:#fff;stroke-width:4px}.map-caption{font-size:14px;color:var(--muted)}nav{display:flex;gap:8px;flex-wrap:wrap;margin:30px 0 20px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}article{border:1px solid var(--line);border-radius:14px;background:var(--panel);overflow:hidden;scroll-margin-top:20px}article:target{border-color:var(--mint)}article[hidden]{display:none}.photo{display:block;background:#01090f;aspect-ratio:16/10}.photo img{display:block;width:100%;height:100%;object-fit:contain}.card-body{padding:24px}.card-body>.eyebrow{margin-top:0}.site,footer{font-size:13px;color:var(--muted)}.chips{display:flex;gap:7px;flex-wrap:wrap;margin:18px 0}.chips span{background:#16323a;padding:4px 10px;border-radius:14px;font-size:12px}details{border-top:1px solid var(--line);padding-top:16px;margin-top:16px}summary{cursor:pointer;color:var(--mint);min-height:44px}ul{padding-left:20px}footer{border-top:1px solid var(--line);padding-top:14px;margin-top:22px}.route{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:26px 0}.route>div{background:#10252e;padding:22px;border-radius:12px}.route strong{color:var(--mint)}.end{margin:42px 0;color:var(--muted)}@media(max-width:700px){header{padding-top:38px}.grid,.route{grid-template-columns:1fr}main,header{padding-left:18px;padding-right:18px}.card-body{padding:20px}.map-panel{padding:12px}.map-label{font-size:17px}}
</style></head><body><header><p class="eyebrow">A World Below / Research & world design / 11 November 2026</p><h1>Different worlds.<br>One continuous ocean.</h1><p>A collection of real seabed photographs and nine habitat recipes. Build each region like an aquarium: terrain first, then water conditions, communities, movement and a discovery worth making.</p></header><main>
<p class="note">These are scientific reference images and proposed designs, not screenshots of new game environments. The existing game still contains the vent-garden prototype. Distances, encounter frequency and regional proximity will be compressed for play.</p>
<section class="map-panel" aria-labelledby="map-title"><div class="map-head"><h2 id="map-title">A journey through the mosaic</h2><button id="layout">Try another arrangement</button></div><svg id="map" viewBox="0 0 1000 470" role="img" aria-label="Schematic connections between habitat recipes"></svg><p class="map-caption" id="map-caption">Select a habitat to examine its photo and recipe. This is a schematic design sketch, not a geographic map or the running game generator.</p></section>
<div class="route"><div><strong>1 / Read the terrain</strong><p>Ridges, walls, depressions and sediment fields establish places. Randomness varies the forms inside a coherent region.</p></div><div><strong>2 / Follow the conditions</strong><p>Depth, substrate, food, current and chemical sources determine which communities can live there.</p></div><div><strong>3 / Discover the hotspot</strong><p>Scattered clues lead to a richer colony or rare encounter. Quieter stretches still contain tracks, burrows and small discoveries.</p></div></div>
<p>The deep ocean is not a sunlit planted aquarium. Corals and sponges are animals; most true plants need light. Microbial communities support some dark-ocean food webs. ROV lamps reveal colors that would otherwise be hidden in darkness.</p>
<nav aria-label="Filter habitat references"><button data-filter="all" aria-pressed="true">All nine habitats</button><button data-filter="terrain" aria-pressed="false">Gardens & terrain</button><button data-filter="chemical" aria-pressed="false">Chemical oases</button><button data-filter="foodfall" aria-pressed="false">Food falls</button><button data-filter="deepest" aria-pressed="false">Hadal depths</button></nav><p id="count" aria-live="polite">Showing 9 habitats</p><section class="grid" aria-label="Photographic habitat references">CARDS</section>
<div class="end"><h2>Generate variation, preserve place</h2><p>A world seed creates the regional layout. Returning to the same coordinates should bring back the same geology and established discoveries. Regions blend across space; they do not reroll when you turn around. New worlds or a separately designed expedition mode can use different seeds.</p><p>Prototype pacing target: a readable clue or small discovery every 20–45 seconds of ordinary swimming, with larger destinations around 1–3 minutes apart. These are design targets to test, not scientific densities or implemented guarantees.</p><p><a href="provenance.json">Photo provenance & checksums</a> · <a href="../../data/habitat_recipes.json">Recipe data in the repository</a> · <a href="../HABITAT_WORLD_DESIGN.md">World design document in the repository</a></p><p>Photos: NOAA public-domain works, plus Jamieson et al. (2022), Figure 4, CC BY 4.0. Credits and source links accompany each image. No scientific organization endorses this game.</p></div>
</main><script>
const positions=[['coral',170,110,'Coral terraces'],['sponge',340,75,'Sponge garden'],['canyon',430,210,'Canyon walls'],['vent',165,310,'Vent field'],['seep',565,105,'Cold seep'],['brine',755,70,'Brine margin'],['nodules',660,300,'Nodule plain'],['whale',495,385,'Whale fall'],['hadal',870,365,'Hadal trench']];
const edges=[[0,1],[0,2],[0,3],[1,4],[2,4],[4,5],[2,6],[6,7],[6,8]];let seed=731942;
function random(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296}
function draw(){const p=positions.map(a=>[a[0],a[1]+(random()-.5)*55,a[2]+(random()-.5)*45,a[3]]);document.querySelector('#map').innerHTML='<defs><linearGradient id="water"><stop stop-color="#194751"/><stop offset="1" stop-color="#0a1e32"/></linearGradient></defs><path d="M0 190 Q250 80 460 245 T1000 380 L1000 470 L0 470Z" fill="url(#water)" opacity=".65"/>'+edges.map(([a,b])=>`<path d="M${p[a][1]},${p[a][2]} Q${(p[a][1]+p[b][1])/2},${Math.min(p[a][2],p[b][2])-25} ${p[b][1]},${p[b][2]}" fill="none" stroke="#528b8c" stroke-width="2" stroke-dasharray="5 6"/>`).join('')+p.map(([id,x,y,label],i)=>`<a class="map-link" href="#${id}"><circle cx="${x}" cy="${y}" r="${id==='whale'?14:23}" fill="${['vent','seep','brine'].includes(id)?'#c49665':id==='hadal'?'#5a85aa':'#4b9d91'}" stroke="#b1d8d0"/><text class="map-label" x="${x}" y="${y+45}" text-anchor="middle">${label}</text></a>`).join('');}
function filter(value){document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===value)));let n=0;document.querySelectorAll('article').forEach(a=>{a.hidden=value!=='all'&&a.dataset.group!==value;if(!a.hidden)n++});document.querySelector('#count').textContent=`Showing ${n} habitat${n===1?'':'s'}`;}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>filter(b.dataset.filter));document.querySelector('#layout').onclick=draw;document.querySelector('#map').onclick=e=>{if(e.target.closest('a'))filter('all')};draw();
</script></body></html>'''.replace('CARDS','\n'.join(cards))
# Link directly to repository documents so standalone deployment has no dead relative paths.
page=page.replace('../../data/habitat_recipes.json','https://github.com/whitewolfcreativeworks-coder/A-World-Below/blob/design/habitat-atlas/data/habitat_recipes.json').replace('../HABITAT_WORLD_DESIGN.md','https://github.com/whitewolfcreativeworks-coder/A-World-Below/blob/design/habitat-atlas/docs/HABITAT_WORLD_DESIGN.md')
(out/'index.html').write_text(page)
print('Built atlas:',len(items),'habitats;',len(meta),'photographs')
